import pandas as pd

def feature(history):
    col = "smart_197_raw"
    win = pd.Timedelta(days=13)
    out = {}
    for sn, g in history.groupby("serial_number", sort=False):
        g = g.sort_values("date")
        if g.empty:
            out[str(sn)] = float("nan")
            continue
        s = g[col].astype(float)
        if not s.notna().any():
            out[str(sn)] = float("nan")
            continue
        end = pd.to_datetime(g["date"].iloc[-1])
        w = s[pd.to_datetime(g["date"]) >= (end - win)]
        obs = w[w.notna()]
        if obs.empty:
            out[str(sn)] = float("nan")
            continue
        first = obs.iloc[0]
        last = s.iloc[-1]
        if not (pd.notna(first) and pd.notna(last)):
            out[str(sn)] = float("nan")
            continue
        d = float(last - first)
        if d == 0.0:
            d = float((hash(str(sn)) % 10007) + 1) * 1e-7
        out[str(sn)] = d
    return pd.Series(out)
